      tipMode: [...TIP_PRESETS, 'custom'].includes(d.tipMode) ? d.tipMode : fallback.tipMode,
      customTipPct: isStr(d.customTipPct) ? d.customTipPct : '',
      currency: CURRENCIES.includes(d.currency) ? d.currency : fallback.currency,
    }
  } catch {
