export function removePerson(bill: Bill, personId: string): Bill {
  return {
    ...bill,
    people: bill.people.filter((p) => p.id !== personId),
    items: bill.items
      .map((it) => ({ ...it, sharedBy: it.sharedBy.filter((id) => id !== personId) }))
      .filter((it) => it.sharedBy.length > 0),
  }
}

